{
  "story": "Retrieval-Augmented Generation enhances large language models by fetching relevant external documents before generating an answer.",
  "aha": {
    "stateId": "generate",
    "observation": "External retrieved knowledge is injected directly into the prompt context to ground the final response."
  },
  "layout": {
    "preset": "pipeline",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "RAG Step",
      "options": [
        "Query",
        "Retrieve",
        "Augment",
        "Generate"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Standard RAG Pipeline",
        "regions": [
          {
            "id": "reg-query",
            "label": "User Query"
          },
          {
            "id": "reg-retriever",
            "label": "Vector Database"
          },
          {
            "id": "reg-augment",
            "label": "Context Assembler"
          },
          {
            "id": "reg-generator",
            "label": "Language Model"
          }
        ],
        "states": [
          {
            "id": "query",
            "label": "1. Query",
            "short": "Query",
            "sentence": "The user submits a prompt asking for specific external facts.",
            "why": "Initializes the information need.",
            "calloutRegion": "reg-query",
            "readouts": [
              {
                "id": "r1",
                "label": "Input Token Count",
                "value": "12"
              }
            ]
          },
          {
            "id": "retrieve",
            "label": "2. Retrieve",
            "short": "Retrieve",
            "sentence": "The system searches the vector database for matching passages.",
            "why": "Finds relevant domain knowledge.",
            "calloutRegion": "reg-retriever",
            "readouts": [
              {
                "id": "r2",
                "label": "Chunks Found",
                "value": "3"
              }
            ]
          },
          {
            "id": "augment",
            "label": "3. Augment",
            "short": "Augment",
            "sentence": "Retrieved documents are merged into the original prompt context.",
            "why": "Provides ground truth data.",
            "calloutRegion": "reg-augment",
            "readouts": [
              {
                "id": "r3",
                "label": "Context Length",
                "value": "840 tokens"
              }
            ]
          },
          {
            "id": "generate",
            "label": "4. Generate",
            "short": "Generate",
            "sentence": "The model produces a factual answer based on the augmented context.",
            "why": "Delivers the final grounded response.",
            "calloutRegion": "reg-generator",
            "readouts": [
              {
                "id": "r4",
                "label": "Confidence Score",
                "value": "0.98"
              }
            ]
          }
        ]
      }
    ]
  }
}
